<script setup>
import {ref,computed,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {request} from './service';import {user} from '@/store';import LinIcon from './LinIcon.vue';
function readLikes(){try{const value=JSON.parse(localStorage.getItem('lin-liked-moments')||'[]');return Array.isArray(value)?value:[];}catch{return [];}}
const route=useRoute(),rows=ref([]),loading=ref(true),error=ref(''),filter=ref('全部'),selected=ref(null),photo=ref(0),liked=ref(readLikes());const kind=computed(()=>route.path==='/albums'?'albums':'moments'),isAlbum=computed(()=>kind.value==='albums');
const filtered=computed(()=>filter.value==='全部'?rows.value:rows.value.filter(r=>r.mood===filter.value));async function load(){loading.value=true;filter.value='全部';try{rows.value=await request('/api/public/journal/'+kind.value);}catch(e){error.value=e.message;}finally{loading.value=false;}}
function favorite(id){liked.value=liked.value.includes(id)?liked.value.filter(x=>x!==id):[...liked.value,id];localStorage.setItem('lin-liked-moments',JSON.stringify(liked.value));}function view(row,i=0){selected.value=row;photo.value=i;}function step(n){photo.value=(photo.value+n+selected.value.images.length)%selected.value.images.length;}
onMounted(load);watch(kind,load);
</script>
<template><main class="lin-journal"><header class="journal-heading"><span class="lin-eyebrow">{{isAlbum?'FRAGMENTS IN FRAMES':'LITTLE THINGS, BIG FEELINGS'}}</span><h1>{{isAlbum?'把瞬间，装进相册。':'不成文章，也值得记下。'}}</h1><p>{{isAlbum?'收集一些光、一点颜色，还有当时的心情。':'零碎的念头、通关后的余味，以及今天想说的话。'}}</p><a v-if="user().getUserInfo.role==='admin'" class="lin-primary" :href="'/admin/'+kind">{{isAlbum?'整理相册':'写条说说'}} <LinIcon name="pen" :size="18"/></a></header><div class="journal-filters"><button v-for="m in ['全部','晴','雨','游戏中','追番中','出走','灵感']" :key="m" :class="{active:filter===m}" @click="filter=m">{{m}}</button><span>{{filtered.length}} {{isAlbum?'本相册':'条心情'}}</span></div><p v-if="error">{{error}}</p><el-skeleton v-if="loading" :rows="6" animated/><div v-else-if="!filtered.length" class="lin-empty"><LinIcon :name="isAlbum?'image':'chat'" :size="45"/><h2>这一页，等下一次灵感。</h2><p>公开的{{isAlbum?'相册':'说说'}}会出现在这里。</p></div><div v-else :class="isAlbum?'album-grid':'moment-stream'"><article v-for="(row,index) in filtered" :key="row.id" :class="isAlbum?'album-card':'moment-card'" :style="{'--delay':Math.min(index,8)*70+'ms'}"><template v-if="isAlbum"><button class="album-cover" @click="view(row)"><img :src="row.images[0].url" :alt="row.title" loading="lazy"/><span>{{String(index+1).padStart(2,'0')}} / {{row.images.length}} FRAMES</span></button><div class="album-copy"><span>{{row.mood}} · {{row.created.slice(0,10)}}</span><h2 v-if="row.title">{{row.title}}</h2><p>{{row.content}}</p></div></template><template v-else><div class="moment-date"><b>{{row.created.slice(8,10)}}</b><span>{{row.created.slice(0,7)}}</span></div><div class="moment-body"><div class="moment-author"><img :src="row.authorAvatar" alt=""/><b>{{row.authorName}}</b></div><span class="moment-mood">{{row.mood}}</span><h2 v-if="row.title">{{row.title}}</h2><p>{{row.content}}</p><div v-if="row.images.length" class="moment-images"><button v-for="(img,i) in row.images" :key="img.url+i" @click="view(row,i)"><img :src="img.url" :alt="img.caption||row.title" loading="lazy"/></button></div><button class="moment-like" :aria-pressed="liked.includes(row.id)" @click="favorite(row.id)"><LinIcon name="heart" :size="16"/>{{liked.includes(row.id)?'已收藏在这台设备':'收藏这份心情'}}</button></div></template></article></div><el-dialog :model-value="!!selected" @update:model-value="v=>{if(!v)selected=null}" class="lin-lightbox" width="min(1000px,94vw)" :title="selected?.title" @keydown.left="step(-1)" @keydown.right="step(1)"><template v-if="selected"><img class="lightbox-image" :src="selected.images[photo].url" :alt="selected.images[photo].caption||selected.title"/><div class="lightbox-footer"><button @click="step(-1)">← 上一张</button><p>{{selected.images[photo].caption||selected.title}} · {{photo+1}} / {{selected.images.length}}</p><button @click="step(1)">下一张 →</button></div></template></el-dialog></main></template>
<style scoped>.moment-author{display:flex;gap:12px;align-items:center;margin-bottom:18px;font-size:13px}.moment-author img{width:35px;height:35px;object-fit:cover;border-radius:12px}</style>
